// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "forge-std/console.sol";

/// @title PoC: Precision Loss / Rounding Error in USDC.totalBackingSigned()
/// @notice Auto-generated scaffold - replace inline math with real contract calls if needed
/// @dev Integer division truncation: (a * b) / c truncates to 0 when a*b < c
contract USDCPrecisionLossTest is Test {

    // ── Inline replica of the vulnerable arithmetic ───────────────────────────
    // Replace this with a call to the actual deployed contract once imports compile.
    function _vulnerable_division(uint256 numerator, uint256 denominator)
        internal pure returns (uint256)
    {
        return numerator / denominator;  // ← truncates toward zero
    }

    // ── Test 1: single small value truncates to zero ─────────────────────────
    // Note: Removed `pure` modifier to allow console.log external calls
    function test_precision_loss_truncates_to_zero() public {
        // With the vulnerable division, profit=5 and feeBps=1000 (10%) over 10_000 base:
        // (5 * 1000) / 10_000 = 5000 / 10_000 = 0  (truncated)
        uint256 smallAmount = 5;
        uint256 rateBps    = 1_000;   // 10 %
        uint256 base       = 10_000;

        console.log("=== Test 1: Single small value truncates to zero ===");
        console.log("smallAmount:", smallAmount);
        console.log("rateBps:", rateBps);
        console.log("base:", base);

        uint256 numerator = smallAmount * rateBps;
        console.log("numerator (smallAmount * rateBps):", numerator);

        uint256 fee = numerator / base;
        console.log("fee (numerator / base):", fee);

        assertEq(fee, 0, "Precision loss: fee truncated to zero for small profitable withdrawal");
    }

    // ── Test 2: accumulated rounding loss over many operations ────────────────
    // Note: Removed `pure` modifier to allow console.log external calls
    function test_precision_loss_accumulated() public {
        uint256 totalExpected;
        uint256 totalActual;
        uint256 rateBps = 1_000;
        uint256 base    = 10_000;

        console.log("=== Test 2: Accumulated rounding loss ===");
        console.log("rateBps:", rateBps);
        console.log("base:", base);

        for (uint256 i = 1; i <= 10; i++) {
            uint256 amount = i; // 1..10 - all below threshold
            console.log("--- Iteration i:", i, " ---");
            console.log("amount:", amount);

            uint256 expectedNum = amount * rateBps + base - 1;
            console.log("expectedNum (amount * rateBps + base - 1):", expectedNum);
            uint256 expectedFee = expectedNum / base;
            console.log("expectedFee (round-up):", expectedFee);
            totalExpected += expectedFee;
            console.log("totalExpected:", totalExpected);

            uint256 actualNum = amount * rateBps;
            console.log("actualNum (amount * rateBps):", actualNum);
            uint256 actualFee = actualNum / base;
            console.log("actualFee (truncation):", actualFee);
            totalActual   += actualFee;
            console.log("totalActual:", totalActual);
        }

        console.log("Final totalExpected:", totalExpected);
        console.log("Final totalActual:", totalActual);

        assertLt(totalActual, totalExpected,
            "Precision loss: accumulated rounding error undercharges fees");
    }

    // ── Test 3: threshold boundary ────────────────────────────────────────────
    // Note: Removed `pure` modifier to allow console.log external calls
    function test_precision_loss_boundary() public {
        uint256 rateBps = 1_000;
        uint256 base    = 10_000;

        console.log("=== Test 3: Threshold boundary ===");
        console.log("rateBps:", rateBps);
        console.log("base:", base);

        // Smallest amount where fee is non-zero
        uint256 threshold = base / rateBps; // 10
        console.log("threshold (base / rateBps):", threshold);

        uint256 belowNum = (threshold - 1) * rateBps;
        console.log("belowNum ((threshold - 1) * rateBps):", belowNum);
        uint256 feeBelow = belowNum / base;
        console.log("feeBelow:", feeBelow);

        uint256 atNum = threshold * rateBps;
        console.log("atNum (threshold * rateBps):", atNum);
        uint256 feeAt = atNum / base;
        console.log("feeAt:", feeAt);

        assertEq(feeBelow, 0, "Just below threshold: fee should be zero (shows truncation)");
        assertGt(feeAt,    0, "At threshold: fee should be non-zero");
    }
}
